// shared-state.js
export const SharedState = {
  data: Object.create(null),

  getType(value) {
    return Object.prototype.toString.call(value).slice(8, -1)
  },

  setData(key, value) {
    // 如果是 Object，遍历赋值
    if (this.getType(key) === 'Object') {
      Object.entries(key).forEach(([k, v]) => this.data[k] = v)
    }
    // 如果是 String，直接赋值
    else if (this.getType(key) === 'String') {
      this.data[key] = value
    }
  },

  getData() {
    return this.data
  },

  clearData() {
    this.data = Object.create(null)
  }
}
